from itertools import permutations

def is_increasing(a):
    return all(a[i] < a[i + 1] for i in range(len(a) - 1))

def find_permutation(n, b):
    for perm in permutations(b):
        a = [perm[0]]
        for i in range(1, n):
            a.append(a[-1] ^ perm[i])
        if is_increasing(a):
            return True, perm
    return False, None

def main():
    n = int(input())
    b = list(map(int, input().split()))

    found, perm = find_permutation(n, b)

    if found:
        print("Yes")
        print(" ".join(map(str, perm)))
    else:
        print("No")

if __name__ == "__main__":
    main()
